  hairMesh.position.copy(head.position); hairMesh.position.y += 0.02; hairMesh.rotation.x = -0.2; rider.add(hairMesh);
  const scarf = new THREE.Mesh(new THREE.TorusGeometry(0.23, 0.055, 4, 12), accentMat);
