      </div>
      <p class="mode-desc">${mode.desc}</p>

      ${sel.mode === 'championship' ? `<div class="champ-banner">
        <div><small>${CHAMPIONSHIP.name}</small><b>${champ ? `Round ${Math.min(3, champ.round + 1)} of 3` : 'Three circuits · points decide everything'}</b></div>
