      <div class="section-title"><span>Select circuit</span><small>Tap a circuit to inspect</small></div>
      <div class="track-scroller scroll-x" id="track-scroller">
        ${TRACKS.map(t => trackCard(t, t.id === sel.trackId, s)).join('')}
