162: 
163: export class UI {
164:   constructor(game) {
165:     this.game = game;
166:     this.state = game.state;
167:     this.current = 'home';
168:     this.modal = null;
169:     this.hudEls = {};
170:     this.lastComment = '';
171:     this.els = {
172:       topbar: document.getElementById('topbar'),
173:       screen: document.getElementById('screen'),
174:       nav: document.getElementById('nav'),
175:       hud: document.getElementById('hud'),
176:       modal: document.getElementById('modal-root'),
177:       toast: document.getElementById('toast-root'),
178:       fade: document.getElementById('fade'),
179:       loading: document.getElementById('loading'),
180:     };
181:     this.els.screen.addEventListener('click', e => this.handleClick(e));
182:     this.els.screen.addEventListener('change', e => this.handleChange(e));
183:     this.els.screen.addEventListener('input', e => this.handleInput(e));
184:     this.els.topbar.addEventListener('click', e => this.handleClick(e));
185:     this.els.nav.addEventListener('click', e => this.handleClick(e));
186:     this.els.modal.addEventListener('click', e => {
187:       const bd = e.target.closest('.modal-backdrop');
188:       if (bd && !bd.dataset.sticky) this.closeModal();
189:       const el = e.target.closest('[data-action]');
190:       if (el) {
191:         e.preventDefault();
192:         this.game.audio.sfx('click');
193:         if (el.dataset.action.startsWith('onboard-')) { this.handleOnboard(el); return; }
194:         this.game.handleUI(el.dataset.action, el.dataset.value, el.dataset);
195:       }
196:     });
197:     this.els.hud.addEventListener('click', e => {
198:       const el = e.target.closest('[data-action]');
199:       if (el) {
200:         e.preventDefault();
201:         this.game.audio.sfx('click');
202:         this.game.handleUI(el.dataset.action, el.dataset.value, el.dataset);
203:       }
204:     });
205:     this.renderChrome();
206:   }
207: 
208:   hideLoading() {
209:     this.els.loading?.classList.add('gone');
210:     setTimeout(() => this.els.loading?.remove(), 900);
211:   }
212: 
213:   renderChrome() {
214:     const s = this.state;
215:     const inGame = !!this.game.active || this.game.mode === 'preview';
216:     this.els.topbar.classList.toggle('hidden', inGame);
217:     this.els.nav.classList.toggle('hidden', inGame);
218:     document.body.classList.toggle('in-game', inGame);
219:     document.body.classList.toggle('in-menu', !inGame);
220:     const level = s.profile.level;
221:     const rank = rankName(s.profile.ranking);
222:     this.els.topbar.innerHTML = `
223:       <button class="profile-chip" data-action="go" data-value="career">
224:         <span class="avatar" style="background:linear-gradient(145deg,${s.profile.robe},#141b2d)"><i>${initials(s.profile.name)}</i></span>
225:         <span class="profile-meta"><small>LEVEL ${level} · ${rank}</small><b>${escapeHtml(s.profile.name)}</b></span>
226:       </button>
227:       <div class="top-right">
228:         <span class="currency">${icon('coin')} <b>${s.profile.galleons.toLocaleString()}</b></span>
229:         <button class="icon-btn" data-action="settings" aria-label="Settings">${icon('settings')}</button>
230:       </div>`;
231:     const nav = [
232:       ['home', 'home', 'Home'], ['race', 'broom', 'Racing'], ['quid', 'quaffle', 'Quidditch'],
233:       ['career', 'trophy', 'Career'], ['locker', 'star', 'Locker'],
234:     ];
235:     this.els.nav.innerHTML = nav.map(([id, ic, label]) => `
236:       <button class="nav-btn ${this.current === id ? 'active' : ''}" data-action="go" data-value="${id}">
237:         ${icon(ic)}<span>${label}</span>
238:       </button>`).join('');
239:   }
240: 
241:   go(name, opts = {}) {
242:     const prevScroll = opts.preserve ? this.els.screen.scrollTop : 0;
243:     this.current = name;
244:     this.render();
245:     this.renderChrome();
246:     if (opts.preserve) requestAnimationFrame(() => { this.els.screen.scrollTop = prevScroll; });
247:     else this.els.screen.scrollTop = 0;
248:   }
249: 
250:   render() {
251:     const game = this.game;
252:     const s = this.state;
253:     switch (this.current) {
254:       case 'home': this.els.screen.innerHTML = this.homeScreen(); break;
255:       case 'race': this.els.screen.innerHTML = this.raceScreen(); break;
256:       case 'quid': this.els.screen.innerHTML = this.quidScreen(); break;
257:       case 'career': this.els.screen.innerHTML = this.careerScreen(); break;
258:       case 'locker': this.els.screen.innerHTML = this.lockerScreen(); break;
259:       default: this.els.screen.innerHTML = this.homeScreen();
260:     }
261:   }
262: 
263:   rerender() {
264:     const scroll = this.els.screen.scrollTop;
265:     this.renderChrome();
266:     this.render();
267:     requestAnimationFrame(() => { this.els.screen.scrollTop = scroll; });
268:   }
269: 
270:   handleClick(e) {
271:     const el = e.target.closest('[data-action]');
272:     if (!el) return;
273:     e.preventDefault();
274:     this.game.audio.init();
275:     this.game.audio.sfx('click');
276:     if (el.dataset.action.startsWith('onboard-')) { this.handleOnboard(el); return; }
277:     this.game.handleUI(el.dataset.action, el.dataset.value, el.dataset);
278:   }
279: 
280:   handleOnboard(el) {
281:     const field = el.dataset.action.replace('onboard-', '');
282:     if (field === 'house' || field === 'skin' || field === 'robe') {
283:       this.onboardDraft[field] = el.dataset.value;
284:       const cls = `.${field === 'house' ? 'house-option' : field === 'skin' ? 'onboard-skin' : 'onboard-robe'}`;
285:       this.els.modal.querySelectorAll(cls).forEach(n => n.classList.remove('active'));
286:       el.classList.add('active');
287:     }
288:   }
289: 
290:   getOnboarding() {
291:     return {
292:       name: (document.getElementById('onboard-name')?.value || 'Aria Blackwood').trim().slice(0, 24),
293:       nation: document.getElementById('onboard-nation')?.value || 'england',
294:       ...this.onboardDraft,
295:     };
296:   }
297: 
298:   handleChange(e) {
299:     const el = e.target;
300:     if (!el.dataset.field) return;
301:     this.game.handleUIField(el.dataset.field, el.value);
302:   }
303: 
304:   handleInput(e) {
305:     const el = e.target;
306:     if (el.dataset.field === 'name') this.game.state.profile.name = el.value.slice(0, 24);
307:   }
308: 
309:   toast(text, sub = '', iconName = 'spark') {
310:     const node = document.createElement('div');
311:     node.className = 'toast';
312:     node.innerHTML = `<span class="toast-icon">${icon(iconName)}</span><div><b>${escapeHtml(text)}</b>${sub ? `<small>${escapeHtml(sub)}</small>` : ''}</div>`;
313:     this.els.toast.appendChild(node);
314:     requestAnimationFrame(() => node.classList.add('in'));
315:     setTimeout(() => {
316:       node.classList.remove('in');
317:       setTimeout(() => node.remove(), 400);
318:     }, 3000);
319:   }
320: 
321:   showModal(html, opts = {}) {
322:     this.closeModal();
323:     this.els.modal.innerHTML = `<div class="modal-backdrop ${opts.cls || ''}" ${opts.sticky ? 'data-sticky="1"' : ''}><div class="modal-card ${opts.card || ''}" role="dialog">${html}</div></div>`;
324:     requestAnimationFrame(() => this.els.modal.querySelector('.modal-backdrop')?.classList.add('in'));
325:     this.modal = opts;
326:     if (opts.onOpen) opts.onOpen();
327:   }
328: 
329:   closeModal() {
330:     const bd = this.els.modal.querySelector('.modal-backdrop');
331:     if (bd) {
332:       bd.classList.remove('in');
333:       setTimeout(() => { this.els.modal.innerHTML = ''; }, 220);
334:     } else {
335:       this.els.modal.innerHTML = '';
336:     }
337:     this.modal = null;
338:   }
