507:   quidScreen() {
508:     const s = this.state;
509:     const sel = this.game.sel;
510:     const t = s.quidditch.tournament;
511:     const nation = NATIONS.find(n => n.id === (t?.nation || s.profile.nation)) || NATIONS[0];
512:     const fixture = currentFixture(s);
513:     const opp = fixture ? NATIONS.find(n => n.id === fixture.opponentId) : null;
514:     const role = POSITIONS.find(p => p.id === sel.role) || POSITIONS[0];
515:     return `<div class="screen quid-screen">
516:       <header class="screen-head">
517:         <div><span class="eyebrow-small">XIV WORLD CUP</span><h2>Quidditch</h2><p>Represent your nation. Raise the cup.</p></div>
518:         <div class="head-badge quid-badge">${icon('quaffle')}<b>${s.quidditch.wins}</b><small>wins</small></div>
519:       </header>
520: 
521:       ${t ? this.tournamentPanel(t, fixture) : `<div class="campaign-hero">
522:         <div class="campaign-crest">${crest(nation, 'large')}</div>
523:         <div><small>REPRESENTING</small><b>${nation.name}</b><span>${nation.stadium} · ${nation.city}</span></div>
524:         <button class="btn small ghost" data-action="go" data-value="career">${icon('globe')} Ranking</button>
525:       </div>`}
526: 
527:       ${!t || t.champion || t.eliminated ? `
528:       <div class="section-title"><span>Choose your nation</span><small>${t ? 'Start a new campaign' : 'Eight nations. One cup.'}</small></div>
529:       <div class="nation-grid">
