865:           <div><small>Weather</small><b>${weatherLabel(track.weather)}</b></div>
866:         </div>
867:         <p class="briefing-desc">${track.desc}</p>
868:         <div class="briefing-broom">
869:           <div class="briefing-broom-art">${broomArt(broom, LIVERIES.find(l => l.id === s.brooms.livery)?.color)}</div>
