1146:     const sz = (h - pad * 2) / (maxZ - minZ || 1);
1147:     const scale = Math.min(sx, sz);
1148:     const map = (x, z) => [w / 2 + (x - (minX + maxX) / 2) * scale, h / 2 + (z - (minZ + maxZ) / 2) * scale];
1149:     ctx.fillStyle = 'rgba(9,15,25,0.62)';
