513:   openBriefing() {
514:     this.audio.init();
515:     this.ui.closeModal();
516:     if (this.active) this.leaveGame();
517:     const cfg = this.raceConfig();
518:     const world = buildRaceWorld(cfg.track, this.state.settings.quality);
519:     const camera = new THREE.PerspectiveCamera(55, this.aspect, 0.1, 2000);
520:     const gate = world.gates[0];
521:     camera.position.copy(gate.pos).add(new THREE.Vector3(28, 9, 28));
522:     camera.lookAt(gate.pos);
523:     this.previewCfg = cfg;
524:     this.preview = { scene: world.scene, camera, world, t: 0, gate };
525:     this.mode = 'preview';
526:     this.ui.renderChrome();
527:     this.ui.showBriefing();
528:   }
529: 
530:   updatePreview(dt) {
531:     if (!this.preview) return;
532:     const p = this.preview;
533:     p.t += dt;
534:     p.world.update(dt, p.camera);
535:     const a = p.t * 0.22 + 0.5;
536:     const center = p.gate.pos;
537:     const desired = center.clone().add(new THREE.Vector3(Math.cos(a) * 34, 9 + Math.sin(p.t * 0.6) * 2, Math.sin(a) * 34));
538:     p.camera.position.lerp(desired, 1 - Math.exp(-dt * 1.8));
539:     p.camera.lookAt(center);
540:   }
