598:   nextChampRace() {
599:     if (!this.championship || this.championship.finished) { this.go('race'); return; }
600:     this.ui.closeModal();
601:     this.startRace(this.raceConfig());
602:   }
603: 
604:   completeRace(summary) {
605:     if (this._completing) return;
606:     this._completing = true;
607:     try {
608:       const diff = DIFFICULTIES.find(d => d.id === summary.difficulty) || DIFFICULTIES[1];
609:       const pos = summary.pos;
610:       const table = [520, 360, 270, 200, 160, 120];
611:       let base = table[Math.min(5, pos - 1)] || 100;
612:       let xp = [190, 145, 115, 90, 75, 60][Math.min(5, pos - 1)] || 50;
613:       let ranking = [50, 35, 25, 16, 10, 6][Math.min(5, pos - 1)] || 4;
614:       if (summary.mode === 'trial') {
615:         base = 300; xp = 120; ranking = 10;
616:         if (summary.bestLap && summary.bestLap < summary.track.targetLap) {
617:           base += 200; xp += 70; ranking += 6;
618:           this.ui.toast('Target beaten!', `New benchmark on ${summary.track.name}`, 'clock');
619:         }
620:       } else if (summary.mode === 'qualify') {
621:         base = 240; xp = 90; ranking = 8;
622:       }
623:       const reward = {
624:         galleons: Math.round(base * diff.reward),
625:         xp: Math.round(xp * diff.reward),
626:         ranking: Math.round(ranking * diff.reward),
627:       };
628:       recordRace(this.state, {
629:         trackId: summary.trackId, trackName: summary.trackName, pos,
630:         time: summary.totalTime, bestLap: summary.bestLap, mode: summary.mode,
631:         boostTime: summary.boostTime,
632:       });
633: 
634:       let championshipExtras = null;
635:       if (summary.mode === 'championship' && this.championship) {
636:         const rounds = this.championship.tracks.length;
637:         const pts = this.championship.points;
638:         const tablePoints = CHAMPIONSHIP.points;
639:         for (const row of summary.standings) {
640:           const name = row.player ? this.state.profile.name : row.name;
641:           pts[name] = (pts[name] || 0) + (tablePoints[row.pos - 1] || 2);
642:         }
643:         const completedRound = this.championship.round;
644:         const final = completedRound >= rounds - 1;
645:         let champion = null;
646:         if (final) {
647:           champion = Object.entries(pts).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
648:           this.championship.finished = true;
649:           if (champion === this.state.profile.name && !this.championship.awarded) {
650:             this.championship.awarded = true;
651:             this.state.career.championships += 1;
652:             reward.galleons += 1200;
653:             reward.xp += 500;
654:             reward.ranking += 80;
655:             this.audio.sfx('win');
656:             this.ui.toast('Grand Prix Champion!', 'The International Broom Grand Prix is yours', 'trophy');
657:           }
658:         } else {
659:           this.championship.round += 1;
660:           this.sel.trackId = CHAMPIONSHIP.tracks[this.championship.round];
661:         }
662:         championshipExtras = {
663:           round: completedRound,
664:           final,
665:           champion,
666:           points: { ...pts },
667:         };
668:       }
669: 
670:       const levels = award(this.state, reward);
671:       const achievements = checkAchievements(this.state);
672:       this.save();
673:       this.ui.renderChrome();
674:       this.ui.showRaceResults(summary, reward, {
675:         levels: levels.levels,
676:         achievements,
677:         championship: championshipExtras,
678:       });
679:       this.audio.setMode('menu');
680:       if (levels.levels > 0) this.audio.sfx('win');
681:     } finally {
682:       setTimeout(() => { this._completing = false; }, 500);
683:     }
684:   }
