797:   pauseGame() {
798:     if (!this.active || this.paused || this.active.phase === 'done' || this.active.phase === 'finished') return;
799:     this.paused = true;
800:     this.input.clear();
801:     this.ui.showPause(this.mode === 'quidditch' ? this.active : null);
