540:     for (const ai of this.ais) {
541:       if (ai.finished) {
542:         ai.model.position.y += Math.sin(this.time * 3 + ai.phase) * dt * 0.02;
543:         continue;
544:       }
545:       // rubber banding keeps races close but leaves skill meaningful
546:       const aiScore = (ai.lap - 1 + ai.u);
547:       const playerScore = this.player.passed / this.N;
548:       let rubber = 0;
549:       if (aiScore < playerScore - 0.08) rubber = 0.065;
550:       if (aiScore > playerScore + 0.12) rubber = -0.04;
551:       const speed = ai.baseSpeed * this.difficulty.ai * (1 + rubber) * (this.weatherType === 'storm' ? 0.9 : 1);
552:       ai.u += (speed * dt) / len;
553:       ai.lap += Math.floor(ai.u);
554:       ai.u = ((ai.u % 1) + 1) % 1;
