307:   if (!t || t.eliminated || t.champion) return null;
308:   const round = t.rounds[t.round];
309:   if (!round) return null;
310:   const match = round.matches.find(m => m.a === t.nation || m.b === t.nation);
311:   if (!match) return null;
312:   const opponentId = match.a === t.nation ? match.b : match.a;
313:   return { match, opponentId, round: t.round, roundName: round.name };
