316: export function completeTournamentMatch(state, playerScore, opponentScore) {
317:   const t = state.quidditch.tournament;
318:   const fixture = currentFixture(state);
319:   if (!t || !fixture) return { done: true, champion: !!t?.champion, eliminated: !!t?.eliminated };
320:   const m = fixture.match;
321:   m.sa = m.a === t.nation ? playerScore : opponentScore;
322:   m.sb = m.a === t.nation ? opponentScore : playerScore;
323:   m.winner = playerScore >= opponentScore ? t.nation : fixture.opponentId;
324:   m.played = true;
325:   const won = m.winner === t.nation;
326: 
327:   if (!won) {
328:     t.eliminated = true;
329:     return { done: true, won, champion: false, eliminated: true, roundName: fixture.roundName };
330:   }
331:   if (t.round >= 2) {
332:     t.champion = true;
333:     state.career.cups += 1;
334:     return { done: true, won, champion: true, eliminated: false, roundName: fixture.roundName };
335:   }
336: 
337:   // Build the next round from this round's winners.
338:   const winners = t.rounds[t.round].matches.map(x => x.winner);
339:   const nextName = ROUND_NAMES[t.round + 1];
340:   let matches;
341:   if (t.round === 0) {
342:     matches = [
343:       { a: winners[0], b: winners[1], player: winners[0] === t.nation || winners[1] === t.nation, played: false },
344:       { a: winners[2], b: winners[3], player: winners[2] === t.nation || winners[3] === t.nation, played: false },
345:     ];
346:   } else {
347:     matches = [{ a: winners[0], b: winners[1], player: true, played: false }];
348:   }
349:   for (const nm of matches) {
350:     if (!nm.player) {
351:       nm.sa = simulateScore();
352:       nm.sb = simulateScore();
353:       nm.winner = nm.sa >= nm.sb ? nm.a : nm.b;
354:       nm.played = true;
355:     }
356:   }
357:   t.round += 1;
358:   t.rounds.push({ name: nextName, matches });
359:   return { done: false, won, champion: false, eliminated: false, roundName: fixture.roundName };
360: }
