/* ================================================================== */
/* Wizarding World Cup — mobile-first interface                        */
/* ================================================================== */

:root {
  --ink: #05070d;
  --ink-2: #090d18;
  --panel: rgba(15, 21, 36, 0.82);
  --panel-solid: #111827;
  --line: rgba(236, 218, 174, 0.14);
  --line-strong: rgba(236, 218, 174, 0.3);
  --cream: #f6efdc;
  --muted: #a9adba;
  --muted-2: #7f8798;
  --gold: #e9c46a;
  --gold-hot: #ffdc8b;
  --gold-deep: #b07d29;
  --gold-wash: rgba(233, 196, 106, 0.14);
  --green: #7fd6a4;
  --red: #e57272;
  --violet: #b699ff;
  --ice: #8fd8ef;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius: 22px;
  --nav-h: 74px;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
}

* { box-sizing: border-box; }

html, body { height: 100%; margin: 0; padding: 0; }

body {
  background: #04060b;
  color: var(--cream);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.45;
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button, input, select { font: inherit; color: inherit; touch-action: manipulation; }
button { cursor: pointer; border: 0; background: none; }
button:disabled { cursor: default; }
h1, h2, h3, h4, h5, p { margin: 0; }
svg { display: block; }
::selection { background: rgba(233, 196, 106, 0.35); }

/* -------- 3D canvas & atmosphere ---------------------------------- */

#gl { position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }

#vignette {
  position: fixed; inset: 0; z-index: 1; pointer-events: none;
  background:
    radial-gradient(120% 70% at 50% -10%, rgba(29, 45, 85, 0.1), transparent 60%),
    linear-gradient(180deg, rgba(3, 5, 10, 0.28) 0%, transparent 22%, rgba(3, 5, 10, 0.06) 55%, rgba(3, 5, 10, 0.66) 100%);
}

#app {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 560px;
  height: 100dvh;
  margin: 0 auto;
  overflow: hidden;
  isolation: isolate;
}

@media (min-width: 720px) {
  body { background: #03050a; }
  #app {
    border-left: 1px solid rgba(233, 196, 106, 0.1);
    border-right: 1px solid rgba(233, 196, 106, 0.1);
    box-shadow: 0 0 90px rgba(0, 0, 0, 0.65);
    background: linear-gradient(180deg, rgba(5, 8, 15, 0.18), rgba(5, 8, 15, 0.42));
  }
}

.icon { width: 18px; height: 18px; flex: none; }
.eyebrow-small {
  display: block; font-size: 9.5px; font-weight: 700; letter-spacing: 0.24em;
  color: var(--gold); text-transform: uppercase; margin-bottom: 5px;
}
.hidden { opacity: 0 !important; pointer-events: none !important; }

/* -------- Loading -------------------------------------------------- */

.loading {
  position: fixed; inset: 0; z-index: 200;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 12px; background: radial-gradient(circle at 50% 38%, #16203a 0%, #080b15 46%, #03050a 100%);
  transition: opacity 0.8s var(--ease), visibility 0.8s;
}
.loading.gone { opacity: 0; visibility: hidden; }
.loading-mark { position: relative; width: 96px; height: 96px; display: grid; place-items: center; margin-bottom: 6px; }
.loading-glyph { font-size: 34px; color: var(--gold-hot); text-shadow: 0 0 28px rgba(255, 214, 120, 0.85); animation: pulse-glow 2s infinite var(--ease); }
.loading-ring { position: absolute; inset: 0; border: 1px solid rgba(233, 196, 106, 0.38); border-radius: 50%; border-top-color: var(--gold-hot); animation: spin 2.2s linear infinite; }
.loading-ring.alt { inset: 12px; border-color: rgba(182, 153, 255, 0.25); border-bottom-color: rgba(182, 153, 255, 0.8); animation-direction: reverse; animation-duration: 1.5s; }
.loading h1 { font-family: var(--serif); font-size: 40px; font-weight: 500; line-height: 0.92; text-align: center; letter-spacing: -0.01em; }
.loading h1 em { color: var(--gold); font-style: italic; }
.loading p { color: var(--muted); font-size: 12px; letter-spacing: 0.16em; text-transform: uppercase; }
.loading-bar { width: 150px; height: 2px; background: rgba(255, 255, 255, 0.1); border-radius: 2px; overflow: hidden; margin-top: 12px; }
.loading-bar i { display: block; height: 100%; width: 40%; background: linear-gradient(90deg, transparent, var(--gold-hot), transparent); animation: load-slide 1.4s infinite var(--ease); }
@keyframes load-slide { 0% { transform: translateX(-120%); } 100% { transform: translateX(300%); } }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse-glow { 0%, 100% { opacity: 0.65; transform: scale(0.96); } 50% { opacity: 1; transform: scale(1.05); } }

/* -------- Top bar & navigation ------------------------------------ */

.topbar {
  position: absolute; top: 0; left: 0; right: 0; z-index: 30;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: calc(10px + var(--safe-t)) 16px 18px;
  background: linear-gradient(180deg, rgba(4, 7, 13, 0.88), rgba(4, 7, 13, 0.42) 58%, transparent);
  transition: opacity 0.25s, transform 0.25s;
}
.topbar.hidden { transform: translateY(-12px); }
.profile-chip { display: flex; align-items: center; gap: 9px; padding: 4px 8px 4px 4px; border-radius: 999px; text-align: left; }
.profile-chip:active { background: rgba(255, 255, 255, 0.06); }
.avatar {
  width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid rgba(255, 220, 140, 0.55); box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.45), 0 3px 12px rgba(0, 0, 0, 0.4);
}
.avatar i { font-style: normal; font-size: 12px; font-weight: 800; letter-spacing: 0.04em; color: #fff4d9; }
.profile-meta { display: flex; flex-direction: column; gap: 1px; }
.profile-meta small { font-size: 8.5px; font-weight: 700; letter-spacing: 0.14em; color: var(--gold); white-space: nowrap; }
.profile-meta b { font-size: 13px; font-weight: 650; letter-spacing: 0.01em; }
.top-right { display: flex; align-items: center; gap: 7px; }
.currency {
  display: inline-flex; align-items: center; gap: 5px; height: 32px; padding: 0 10px;
  border: 1px solid rgba(233, 196, 106, 0.24); border-radius: 999px;
  background: rgba(9, 13, 22, 0.7); backdrop-filter: blur(12px);
  font-size: 12px; color: var(--gold-hot);
}
.currency .icon { width: 14px; height: 14px; }
.currency b { font-weight: 650; color: var(--cream); }
.icon-btn {
  width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid rgba(236, 218, 174, 0.16); background: rgba(10, 14, 24, 0.7);
  color: var(--muted); backdrop-filter: blur(12px); transition: color 0.2s, border-color 0.2s;
}
.icon-btn:active { color: var(--gold-hot); border-color: rgba(233, 196, 106, 0.5); }
.icon-btn .icon { width: 17px; height: 17px; }

.nav {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 40;
  height: calc(var(--nav-h) + var(--safe-b));
  padding: 7px 10px calc(6px + var(--safe-b));
  display: grid; grid-template-columns: repeat(5, 1fr); align-items: start;
  background: linear-gradient(180deg, rgba(10, 14, 24, 0.9), rgba(5, 8, 14, 0.98));
  border-top: 1px solid rgba(233, 196, 106, 0.14);
  box-shadow: 0 -20px 40px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(18px);
  transition: transform 0.3s var(--ease), opacity 0.25s;
}
.nav.hidden { transform: translateY(110%); opacity: 0; }
.nav-btn {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  padding: 7px 2px 0; color: var(--muted-2); position: relative;
  transition: color 0.2s, transform 0.2s;
}
.nav-btn .icon { width: 21px; height: 21px; }
.nav-btn span { font-size: 8.5px; font-weight: 650; letter-spacing: 0.06em; }
.nav-btn.active { color: var(--gold-hot); }
.nav-btn.active::after {
  content: ''; position: absolute; top: -7px; width: 22px; height: 2px; border-radius: 2px;
  background: var(--gold-hot); box-shadow: 0 0 12px rgba(255, 214, 120, 0.9);
}
.nav-btn:active { transform: scale(0.94); }

/* -------- Screens & shared bits ----------------------------------- */

.screen {
  position: absolute; inset: 0; z-index: 5;
  overflow-y: auto; overflow-x: hidden;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: calc(68px + var(--safe-t)) 18px calc(96px + var(--safe-b));
  animation: screen-in 0.4s var(--ease);
}
.screen::-webkit-scrollbar { display: none; }
@keyframes screen-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

.race-screen, .quid-screen, .career-screen, .locker-screen {
  background:
    radial-gradient(120% 55% at 50% 0%, rgba(31, 45, 77, 0.5), transparent 62%),
