}
.home-sheet::before { content: ''; position: absolute; inset: 0 0 auto; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 226, 160, 0.7), transparent); }
.sheet-grip { width: 34px; height: 3px; border-radius: 3px; background: rgba(255, 255, 255, 0.16); margin: 0 auto 12px; }

.continue-card {
