.continue-body small { font-size: 8px; letter-spacing: 0.17em; color: var(--gold); font-weight: 700; }
.continue-body b { font-size: 15px; font-weight: 650; letter-spacing: -0.01em; }
.continue-body .progress { margin: 4px 0 3px; width: 100%; }
.continue-body span { font-size: 9.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.continue-arrow { width: 16px; height: 16px; color: var(--muted-2); flex: none; }

.mode-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 12px; }
.mode-card {
  position: relative; overflow: hidden; min-height: 176px; padding: 14px;
  display: flex; flex-direction: column; align-items: flex-start;
