.mode-icon .icon { width: 21px; height: 21px; }
.mode-card small { font-size: 7.5px; letter-spacing: 0.14em; color: rgba(255, 255, 255, 0.47); font-weight: 700; }
.mode-card b { font-family: var(--serif); font-weight: 500; font-size: 19px; line-height: 1.08; margin: 2px 0 3px; letter-spacing: -0.02em; }
.mode-meta { font-size: 9px; color: rgba(255, 255, 255, 0.48); }
.mode-cta { margin-top: auto; padding-top: 8px; font-size: 10px; font-weight: 650; color: var(--gold); display: flex; align-items: center; gap: 2px; }
.mode-card.quid .mode-cta { color: #cfc0ff; }
.mode-cta .icon { width: 12px; height: 12px; }

.home-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 11px; }
.mini-panel { padding: 10px 12px; border-radius: 14px; border: 1px solid rgba(255, 255, 255, 0.07); background: rgba(255, 255, 255, 0.035); }
.mini-head { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.mini-head span { display: flex; align-items: center; gap: 4px; font-size: 8px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted-2); }
.mini-head span .icon { width: 11px; height: 11px; color: var(--gold); }
.mini-head b { font-size: 13px; font-weight: 650; color: var(--gold-hot); }
.mini-sub { font-size: 9px; color: var(--muted-2); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.news-ticker {
  margin-top: 11px; display: flex; align-items: center; gap: 8px; padding: 8px 10px;
  border-radius: 11px; background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); overflow: hidden;
}
.ticker-live { display: flex; align-items: center; gap: 4px; flex: none; font-size: 7.5px; font-weight: 800; letter-spacing: 0.11em; color: #ff8d7e; }
.ticker-live i { width: 4px; height: 4px; border-radius: 50%; background: #ff6d5c; box-shadow: 0 0 7px #ff6d5c; animation: blink 1.4s infinite; }
@keyframes blink { 50% { opacity: 0.25; } }
.ticker-track { overflow: hidden; flex: 1; white-space: nowrap; -webkit-mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent); mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent); }
.ticker-track span { display: inline-block; font-size: 9px; color: var(--muted); animation: ticker 28s linear infinite; padding-left: 10%; }
@keyframes ticker { from { transform: translateX(0); } to { transform: translateX(-100%); } }
.home-footer { display: flex; align-items: center; justify-content: center; gap: 5px; color: var(--muted-2); font-size: 8.5px; text-align: center; padding: 14px 0 4px; }
