/* -------- Quidditch hub ------------------------------------------- */

.campaign-hero {
  display: flex; align-items: center; gap: 12px; padding: 13px;
  border-radius: 18px; border: 1px solid rgba(182, 153, 255, 0.18);
  background: radial-gradient(100% 120% at 0% 0%, rgba(152, 123, 255, 0.16), transparent 60%), linear-gradient(135deg, rgba(28, 27, 48, 0.85), rgba(9, 12, 22, 0.85));
}
.campaign-crest .crest.large { box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35); }
.campaign-hero > div:nth-child(2) { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.campaign-hero small { font-size: 7.5px; letter-spacing: 0.14em; color: var(--violet); }
.campaign-hero b { font-family: var(--serif); font-size: 20px; font-weight: 500; }
.campaign-hero span { font-size: 9px; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.campaign-hero .btn { flex: none; }

.nation-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.nation-card {
  display: grid; grid-template-columns: 32px 1fr; grid-template-rows: auto auto; align-items: center; gap: 0 7px;
  padding: 7px 8px; border-radius: 12px; border: 1px solid rgba(255, 255, 255, 0.075);
  background: linear-gradient(120deg, color-mix(in srgb, var(--c1) 10%, transparent), rgba(12, 16, 28, 0.7));
  text-align: left; position: relative;
}
.nation-card .crest { grid-row: span 2; width: 28px; height: 32px; }
.nation-card b { font-size: 10.5px; font-weight: 600; line-height: 1.2; }
.nation-card small { font-size: 8px; color: var(--muted-2); }
.nation-card.selected { border-color: rgba(255, 220, 139, 0.55); box-shadow: inset 0 0 0 1px rgba(255, 220, 139, 0.15); background: linear-gradient(120deg, color-mix(in srgb, var(--c1) 28%, transparent), rgba(12, 16, 28, 0.75)); }
.nation-card.selected::after { content: '✓'; position: absolute; top: 5px; right: 6px; font-size: 9px; color: var(--gold-hot); }
.nation-strip { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px; }
.nation-strip > div { display: flex; align-items: center; gap: 8px; padding: 9px 10px; border-radius: 12px; border: 1px solid rgba(255, 255, 255, 0.06); background: rgba(255, 255, 255, 0.03); }
.nation-strip .icon { width: 18px; height: 18px; color: var(--gold); }
.nation-strip span { display: flex; flex-direction: column; }
.nation-strip small { font-size: 7.5px; color: var(--muted-2); text-transform: uppercase; letter-spacing: 0.06em; }
.nation-strip b { font-size: 10px; font-weight: 600; }

.role-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.role-card {
  display: grid; grid-template-columns: 35px 1fr; grid-template-rows: auto auto; align-items: center; gap: 0 8px;
  padding: 10px; border-radius: 14px; text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.035);
  transition: border-color 0.2s, background 0.2s;
}
.role-icon { grid-row: span 2; width: 35px; height: 35px; border-radius: 11px; display: grid; place-items: center; background: color-mix(in srgb, var(--role) 18%, transparent); border: 1px solid color-mix(in srgb, var(--role) 32%, transparent); color: var(--role); }
.role-icon .icon { width: 18px; height: 18px; }
.role-card b { font-size: 12px; font-weight: 600; }
.role-card small { font-size: 8px; line-height: 1.4; color: var(--muted-2); }
.role-card.active { border-color: color-mix(in srgb, var(--role) 55%, transparent); background: color-mix(in srgb, var(--role) 9%, rgba(10, 14, 24, 0.8)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--role) 15%, transparent); }

.bracket-card { border-radius: 18px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.08); background: linear-gradient(150deg, rgba(23, 28, 44, 0.8), rgba(9, 12, 21, 0.86)); }
.bracket-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 13px; border-bottom: 1px solid rgba(255, 255, 255, 0.07); }
.bracket-head small { display: block; font-size: 7px; letter-spacing: 0.15em; color: var(--violet); }
.bracket-head b { font-size: 11px; font-weight: 600; }
.bracket-status { padding: 4px 8px; border-radius: 999px; font-size: 7.5px; font-weight: 800; letter-spacing: 0.09em; text-transform: uppercase; background: rgba(233, 196, 106, 0.14); color: var(--gold-hot); border: 1px solid rgba(233, 196, 106, 0.25); }
.bracket-status.champion { background: rgba(127, 214, 164, 0.14); color: #9af0bd; border-color: rgba(127, 214, 164, 0.3); }
.bracket-status.out { background: rgba(229, 114, 114, 0.12); color: #ff9e9e; border-color: rgba(229, 114, 114, 0.28); }
.bracket { display: flex; gap: 8px; overflow-x: auto; padding: 10px; scrollbar-width: none; }
.bracket::-webkit-scrollbar { display: none; }
.bracket-round { flex: none; width: 139px; }
.bracket-round h5 { margin: 0 0 5px 2px; font-size: 7.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted-2); font-weight: 650; }
.bracket-round.current h5 { color: var(--gold); }
.bracket-match { padding: 4px; margin-bottom: 5px; border-radius: 7px; background: rgba(255, 255, 255, 0.035); border: 1px solid rgba(255, 255, 255, 0.06); }
.bracket-match.involved { border-color: rgba(182, 153, 255, 0.34); background: rgba(182, 153, 255, 0.08); }
.bracket-match > span { display: grid; grid-template-columns: 18px 1fr auto; align-items: center; gap: 4px; padding: 1px 2px; }
.bracket-match .crest { width: 16px; height: 18px; border-radius: 3px 3px 5px 5px; }
.bracket-match .crest::after, .bracket-match .crest i { display: none; }
.bracket-match .crest b { font-size: 4.5px; margin-top: 6px; }
.bracket-match b { font-size: 8px; font-weight: 600; color: var(--muted); }
.bracket-match i { font-style: normal; font-size: 8.5px; font-weight: 700; color: var(--muted-2); }
.bracket-match span.winner b, .bracket-match span.winner i { color: var(--cream); }
.next-fixture { display: flex; align-items: center; gap: 7px; padding: 9px 12px; border-top: 1px solid rgba(255, 255, 255, 0.06); background: rgba(233, 196, 106, 0.055); }
.next-fixture span { font-size: 6.5px; letter-spacing: 0.13em; font-weight: 800; color: var(--gold); }
.next-fixture b { font-size: 9.5px; font-weight: 600; }
.next-fixture small { font-size: 8px; color: var(--muted-2); margin-left: auto; text-align: right; }
.champion-banner { display: flex; align-items: center; justify-content: center; gap: 6px; padding: 11px; font-size: 10px; font-weight: 800; letter-spacing: 0.14em; color: #251903; background: linear-gradient(90deg, #c5983d, #ffe4a0, #c5983d); }
.champion-banner .icon { width: 15px; height: 15px; }
.eliminated-banner { padding: 11px 13px; border-radius: 12px; font-size: 9.5px; text-align: center; color: #ffb7b7; background: rgba(229, 114, 114, 0.1); border: 1px solid rgba(229, 114, 114, 0.22); }
