.house-option.active { border-color: rgba(233, 196, 106, 0.45); background: rgba(233, 196, 106, 0.07); }
.onboarding .btn { margin-top: 5px; }

/* -------- Briefing ------------------------------------------------- */

.briefing-card { overflow: hidden; }
.briefing-art { position: relative; height: 208px; overflow: hidden; }
.briefing-art .art-orb { width: 230px; height: 230px; top: -110px; right: -50px; opacity: 1; }
.briefing-art .art-landmark { height: 150px; opacity: 0.95; }
.briefing-fade { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(5, 8, 14, 0.06), rgba(5, 8, 14, 0.28) 46%, rgba(6, 9, 16, 0.96) 100%); }
.floating-close { position: absolute; top: 12px; right: 12px; z-index: 5; color: var(--cream); background: rgba(5, 8, 14, 0.5); border-color: rgba(255, 255, 255, 0.2); }
.briefing-title { position: absolute; left: 18px; right: 18px; bottom: 12px; z-index: 3; }
.briefing-title small { font-size: 7.5px; letter-spacing: 0.16em; color: var(--gold); }
.briefing-title h2 { font-family: var(--serif); font-size: 32px; font-weight: 500; line-height: 1; letter-spacing: -0.03em; margin: 2px 0 3px; text-shadow: 0 3px 18px rgba(0, 0, 0, 0.7); }
.briefing-title span { font-size: 9.5px; color: rgba(255, 255, 255, 0.7); line-height: 1.4; display: block; }
.briefing-weather { position: absolute; top: 13px; left: 14px; z-index: 3; padding: 5px 9px; border-radius: 999px; font-size: 8px; letter-spacing: 0.04em; background: rgba(5, 8, 14, 0.48); border: 1px solid rgba(255, 255, 255, 0.16); backdrop-filter: blur(8px); display: flex; flex-direction: column; gap: 0; }
