.briefing-broom { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 12px; background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.065); }
.briefing-broom-art { width: 88px; height: 44px; flex: none; }
.briefing-broom > div:last-child { min-width: 0; }
.briefing-broom small { display: block; font-size: 6.5px; letter-spacing: 0.13em; color: var(--gold); }
.briefing-broom b { display: block; font-size: 11px; font-weight: 600; }
.briefing-rewards { display: flex; justify-content: center; gap: 8px; margin: 11px 0 7px; }
.briefing-rewards span { display: inline-flex; align-items: center; gap: 3px; font-size: 9px; color: var(--gold-hot); padding: 4px 8px; border-radius: 999px; background: rgba(233, 196, 106, 0.08); border: 1px solid rgba(233, 196, 106, 0.15); }
.briefing-rewards .icon { width: 11px; height: 11px; }
.briefing-tip { display: flex; align-items: flex-start; gap: 5px; font-size: 8.5px; line-height: 1.45; color: var(--muted-2); padding: 7px 9px; border-radius: 10px; background: rgba(143, 216, 239, 0.05); border: 1px solid rgba(143, 216, 239, 0.1); }
.briefing-tip .icon { width: 12px; height: 12px; color: var(--ice); margin-top: 1px; }
.briefing-actions { display: flex; gap: 8px; margin-top: 12px; }
.briefing-actions .btn { flex: 1; }

/* -------- Results -------------------------------------------------- */

.results-card { overflow: hidden; }
.results-hero { position: relative; overflow: hidden; padding: 22px 18px 16px; text-align: center; background: radial-gradient(120% 120% at 50% 0%, rgba(76, 63, 34, 0.6), transparent 60%), linear-gradient(170deg, #172034, #0b101d 70%); }
.results-hero.podium { background: radial-gradient(120% 120% at 50% 0%, rgba(233, 196, 106, 0.28), transparent 58%), linear-gradient(170deg, #222c3f, #0d111d 70%); }
.results-rays { position: absolute; left: 50%; top: -110px; width: 340px; height: 340px; transform: translateX(-50%); background: repeating-conic-gradient(from 0deg, rgba(255, 220, 139, 0.1) 0deg 6deg, transparent 6deg 18deg); -webkit-mask-image: radial-gradient(circle, #000 0%, transparent 66%); mask-image: radial-gradient(circle, #000 0%, transparent 66%); opacity: 0.7; pointer-events: none; }
.results-hero > * { position: relative; z-index: 1; }
.big-rank { font-family: var(--serif); font-size: 62px; font-weight: 500; line-height: 0.9; letter-spacing: -0.04em; color: var(--gold-hot); text-shadow: 0 0 30px rgba(255, 214, 120, 0.25); }
