.result-table { margin-top: 10px; border-radius: 11px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.065); }
.result-head, .result-row { display: grid; grid-template-columns: 21px 1fr auto; align-items: center; gap: 5px; padding: 5px 9px; }
.result-head { background: rgba(255, 255, 255, 0.05); font-size: 6.5px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted-2); }
