.pause-score { display: flex; align-items: center; justify-content: center; gap: 14px; padding: 10px 18px 4px; }
.pause-score > div { display: flex; flex-direction: column; align-items: center; }
.pause-score small { font-size: 7.5px; color: var(--muted-2); text-transform: uppercase; letter-spacing: 0.06em; }
.pause-score b { font-family: var(--serif); font-size: 32px; font-weight: 500; line-height: 1; }
.pause-score > span { font-size: 9px; color: var(--muted-2); }
.sub-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; margin: 0 14px; }
.sub-btn { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 6px 2px; border-radius: 9px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.026); font-size: 7px; color: var(--muted); }
