.pause-actions { display: flex; flex-direction: column; gap: 6px; padding: 14px 18px 0; }
.pause-actions .btn { width: 100%; height: 40px; font-size: 11px; }
.pause-card .seg-chips { margin: 0 14px; }
.pause-card .fineprint { padding: 0 18px; }

/* -------- Toast and fade ------------------------------------------ */

.toast-root { position: fixed; left: 50%; bottom: calc(var(--nav-h) + var(--safe-b) + 16px); transform: translateX(-50%); z-index: 150; display: flex; flex-direction: column-reverse; gap: 6px; width: min(92vw, 420px); pointer-events: none; }
.toast { display: flex; align-items: center; gap: 8px; padding: 9px 12px; border-radius: 13px; background: rgba(13, 18, 30, 0.96); border: 1px solid rgba(233, 196, 106, 0.25); box-shadow: 0 12px 34px rgba(0, 0, 0, 0.5); opacity: 0; transform: translateY(8px) scale(0.98); transition: all 0.3s var(--ease); backdrop-filter: blur(14px); }
.toast.in { opacity: 1; transform: none; }
.toast-icon { width: 28px; height: 28px; flex: none; border-radius: 8px; display: grid; place-items: center; background: rgba(233, 196, 106, 0.12); color: var(--gold-hot); }
.toast-icon .icon { width: 14px; height: 14px; }
.toast b { display: block; font-size: 10.5px; font-weight: 650; }
.toast small { display: block; font-size: 8.5px; color: var(--muted-2); }
.fade { position: fixed; inset: 0; z-index: 180; background: #04060b; opacity: 0; pointer-events: none; transition: opacity 0.25s; }
.fade.show { opacity: 1; pointer-events: auto; }
