.action-cluster { position: absolute; right: 17px; bottom: calc(22px + var(--safe-b)); display: flex; align-items: flex-end; gap: 10px; pointer-events: none; }
.round-btn {
  width: 68px; height: 68px; border-radius: 50%; position: relative; overflow: hidden;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  pointer-events: auto; color: var(--cream);
  background: radial-gradient(circle at 38% 28%, rgba(255, 255, 255, 0.18), rgba(20, 26, 38, 0.86) 55%, rgba(7, 10, 18, 0.92));
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: transform 0.08s, filter 0.15s;
}
.round-btn .icon { width: 23px; height: 23px; }
.round-btn span { font-size: 6.5px; font-weight: 800; letter-spacing: 0.1em; }
.round-btn.boost { width: 78px; height: 78px; color: #ffe6a4; border-color: rgba(233, 196, 106, 0.48); background: radial-gradient(circle at 38% 28%, rgba(255, 227, 160, 0.34), rgba(84, 66, 32, 0.8) 55%, rgba(22, 18, 12, 0.94)); }
.round-btn.boost .icon { width: 27px; height: 27px; }
