.round-btn.pass .icon { width: 18px; height: 18px; }
.round-btn.pass span { font-size: 5.5px; }
.cooldown-ring { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(rgba(5, 8, 14, 0.72) var(--cd, 0deg), transparent var(--cd, 0deg)); pointer-events: none; }
.hud.boosting .speedlines { opacity: 1; }
.speedlines {
  position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity 0.3s;
  background: repeating-conic-gradient(from 0deg at 50% 58%, transparent 0deg 5deg, rgba(255, 244, 210, 0.07) 5.5deg 6deg, transparent 6.5deg 11deg);
