  mask-image: radial-gradient(ellipse at 50% 58%, transparent 20%, #000 70%);
  animation: speedlines 0.45s linear infinite;
}
@keyframes speedlines { to { transform: scale(1.06) rotate(1.4deg); } }
.hit-flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(circle, transparent 38%, rgba(220, 64, 48, 0.5) 100%); }
.hud.hit .hit-flash { animation: hit-flash 0.45s ease-out; }
