/* Quidditch HUD */
.scoreboard {
  position: absolute; top: calc(8px + var(--safe-t)); left: 10px; right: 10px; z-index: 4;
  display: flex; align-items: center; justify-content: center; gap: 8px; padding: 5px 9px; border-radius: 15px;
  background: linear-gradient(180deg, rgba(9, 13, 22, 0.84), rgba(9, 13, 22, 0.6));
  border: 1px solid rgba(255, 255, 255, 0.12); backdrop-filter: blur(14px); box-shadow: 0 8px 26px rgba(0, 0, 0, 0.3);
}
.team-block { display: flex; align-items: center; gap: 5px; min-width: 0; flex: 1; }
.team-block > div { display: flex; flex-direction: column; line-height: 1; min-width: 0; }
.team-block small { font-size: 6.5px; letter-spacing: 0.06em; color: var(--muted); text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 58px; }
.team-block b { font-family: var(--serif); font-size: 25px; font-weight: 500; line-height: 1.1; color: var(--cream); }
.opp-team { flex-direction: row-reverse; text-align: right; }
.opp-team > div { align-items: flex-end; }
.opp-team .crest { --c1: var(--c); }
.match-clock { flex: none; display: flex; flex-direction: column; align-items: center; padding: 0 2px; position: relative; }
.match-clock small { font-size: 5.5px; letter-spacing: 0.12em; color: var(--gold); text-transform: uppercase; }
.match-clock b { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.15; }
.match-clock b.urgent { color: #ff9f8b; animation: blink 1s infinite; }
.clock-underline { width: 26px; height: 1px; background: rgba(233, 196, 106, 0.4); }
.scoreboard .hud-pause { position: absolute; right: 7px; top: 50%; transform: translateY(-50%); width: 27px; height: 27px; }
.scoreboard .hud-pause .icon { width: 12px; height: 12px; }

.quid-commentary {
  position: absolute; top: calc(60px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  width: min(88vw, 400px); text-align: center; font-size: 9px; line-height: 1.35; color: #eee9dd;
  padding: 5px 10px; border-radius: 9px; background: rgba(7, 11, 20, 0.55); border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px); opacity: 0.9;
}
.quid-commentary span { color: var(--gold); }
.quid-commentary.flash { animation: comment-flash 0.5s var(--ease); }
@keyframes comment-flash { 0% { transform: translateX(-50%) scale(0.95); opacity: 0.55; } 100% { transform: translateX(-50%); opacity: 1; } }
.quid-objective {
  position: absolute; top: calc(92px + var(--safe-t)); left: 10px; z-index: 2; max-width: 60vw;
  display: flex; align-items: center; gap: 4px; flex-wrap: wrap; padding: 5px 8px; border-radius: 8px;
  background: rgba(7, 11, 20, 0.55); border: 1px solid rgba(255, 255, 255, 0.08); font-size: 8px; color: var(--muted); backdrop-filter: blur(7px);
}
.quid-objective b { font-size: 7px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--gold); }
.obj-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 7px rgba(233, 196, 106, 0.8); }
.quid-objective.danger { border-color: rgba(229, 114, 114, 0.45); color: #ffc0b8; }
.quid-objective.danger .obj-dot { background: #ff7c65; box-shadow: 0 0 9px #ff7c65; animation: blink 0.8s infinite; }
.quid-warning { position: absolute; z-index: 5; top: 25%; left: 50%; transform: translateX(-50%); padding: 6px 13px; border-radius: 999px; font-size: 9px; font-weight: 800; letter-spacing: 0.12em; color: #fff0e9; background: rgba(167, 46, 34, 0.86); border: 1px solid rgba(255, 150, 130, 0.5); opacity: 0; transition: opacity 0.2s; white-space: nowrap; }
.quid-warning.show { opacity: 1; animation: warn-pulse 0.8s infinite; }
@keyframes warn-pulse { 50% { box-shadow: 0 0 26px rgba(255, 86, 64, 0.45); } }
.role-chip { position: absolute; z-index: 2; top: calc(125px + var(--safe-t)); left: 10px; display: flex; align-items: center; gap: 4px; padding: 4px 8px; border-radius: 999px; font-size: 7.5px; font-weight: 650; color: var(--gold-hot); background: rgba(7, 11, 20, 0.55); border: 1px solid rgba(233, 196, 106, 0.24); backdrop-filter: blur(7px); }
.role-chip .icon { width: 10px; height: 10px; }
.quid-boost { position: absolute; z-index: 2; left: 22px; bottom: calc(150px + var(--safe-b)); width: 106px; }
.quid-actions { position: absolute; z-index: 6; right: 14px; bottom: calc(22px + var(--safe-b)); display: flex; align-items: flex-end; gap: 7px; }
.quid-actions .round-btn.boost { width: 60px; height: 60px; }
.quid-actions .round-btn.boost .icon { width: 22px; height: 22px; }
.quid-banner {
  position: absolute; z-index: 6; left: 50%; top: 31%; transform: translate(-50%, 8px);
  padding: 8px 16px; border-radius: 999px; white-space: nowrap;
  font-size: 10px; font-weight: 800; letter-spacing: 0.12em; color: #241804;
  background: linear-gradient(90deg, #d7ad50, #ffe6a6, #d7ad50);
  box-shadow: 0 8px 30px rgba(233, 196, 106, 0.3); opacity: 0; transition: all 0.3s var(--ease); pointer-events: none;
}
.quid-banner.show { opacity: 1; transform: translate(-50%, 0); }
.quid-score-flash { position: absolute; z-index: 7; left: 50%; top: 38%; transform: translate(-50%, 8px) scale(0.94); font-family: var(--serif); font-size: 42px; font-weight: 500; color: var(--gold-hot); text-shadow: 0 0 32px rgba(255, 214, 120, 0.4), 0 4px 16px #000; opacity: 0; transition: all 0.25s var(--ease); pointer-events: none; white-space: nowrap; }
.quid-score-flash.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.quid-score-flash.bad { color: #ffa294; }
.quid-countdown { font-size: 84px; }

@media (max-height: 700px) {
  .home-hero { min-height: 42dvh; padding-top: calc(80px + var(--safe-t)); }
  .home-sheet { min-height: 58dvh; }
  .race-objective { display: none; }
  .speed-panel { bottom: calc(148px + var(--safe-b)); }
  .quid-boost { bottom: calc(140px + var(--safe-b)); }
  .race-minimap-wrap canvas { width: 104px; height: 71px; }
  .quid-minimap-wrap canvas { width: 102px; height: 66px; }
  .joystick { width: 104px; height: 104px; }
  .round-btn { width: 62px; height: 62px; }
  .round-btn.boost { width: 72px; height: 72px; }
  .round-btn.action { width: 74px; height: 74px; }
}

@media (max-width: 360px) {
  .screen { padding-left: 14px; padding-right: 14px; }
  .track-scroller { margin-left: -14px; margin-right: -14px; padding-left: 14px; padding-right: 14px; }
  .seg-chips.scroll-x { margin-left: -14px; margin-right: -14px; padding-left: 14px; padding-right: 14px; }
  .home-hero h1 { font-size: 40px; }
  .mode-card b { font-size: 17px; }
  .country-grid, .nation-grid { gap: 6px; }
  .big-rank { font-size: 54px; }
}

/* Kill text selection while playing */
.in-game .screen, .in-game .hud { user-select: none; -webkit-user-select: none; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; }
}
